findings.fix:
Add an alias for "@" in vite.config.ts (and tsconfig.json) or change the import to a relative path. Example fix:

// vite.config.ts
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import path from 'path';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@': path.resolve(__dirname, 'src')
    }
  }
});

// Also ensure tsconfig.json has:
// {
//   "compilerOptions": {
//     "baseUrl": "./",
//     "paths": { "@/*": ["src/*"] }
//   }
// }

// Or simply change the import to a relative path:
// import Layout from "../components/Layout";
